# Unit titles name the whole sub-topic, so they do not repeat the first sub-heading.
import json
unit_titles={'1.1':'Mathematical skills for biology','1.2.1':'Observing, handling apparatus and planning variables',
 '1.2.2':'Finding and recording information','1.2.3':'Processing data and drawing graphs',
 '1.2.4':'Units, prefixes and standard form','1.2.5':'Errors, anomalies and conclusions',
 '1.2.6':'Practical skills: planning, apparatus, tests and drawings'}
for u in A.wo['content_units']:
    f=A.base/'content-units'/f"{u['unit_id']}.json"
    cu=json.loads(f.read_text())
    cu['title']=u['sub_topic']+' '+unit_titles[u['sub_topic']]
    f.write_text(json.dumps(cu,indent=1,ensure_ascii=False)+'\n')
